    {
      "@id": "activity:translation-story_text_1-2026-07-07T23:16:38.434710+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T23:16:38.434710+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_1",
      "@type": "prov:Entity",
      "prov:value": "Aristotle walked as he taught. He believed the act of moving — through space, through questions, through observation — was itself a form of thinking. Two thousand years later, the research agrees."
    },
    {
      "@id": "entity:target-story_text_1-v1",
      "@type": "prov:Entity",
      "prov:value": "Aristoteles ging und lehrte. Er glaubte, dass das Bewegen - durch den Raum, durch Fragen, durch die Beobachtung - selbst eine Form des Denkens ist. Zweitausend Jahre später stimmt die Forschung ihm zu.",
      "generated_by": {
        "@id": "activity:translation-story_text_1-2026-07-07T23:16:38.434710+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_1"
      }
    },
    {
      "@id": "activity:translation-story_text_2-2026-07-07T23:16:38.434710+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T23:16:38.434710+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_2",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware puts that insight in your pocket. Teachers design activities that bring curriculum to life in the real world. Students explore, capture, and reflect. Peri guides the inquiry. And learning — finally — moves."
    },
    {
      "@id": "entity:target-story_text_2-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware steckt diese Erkenntnis in Ihre Tasche. Lehrer gestalten Aktivitäten, die den Lehrplan im echten Leben lebendig machen. Schüler erkunden, erfassen und reflektieren. Peri leitet die Untersuchung. Und das Lernen - endlich - bewegt sich.",
      "generated_by": {
        "@id": "activity:translation-story_text_2-2026-07-07T23:16:38.434710+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_2"
      }
    },
