      "@id": "entity:target-meet_peri.step.3.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Peri stellt Vergleichsfragen und Klassifizierungsfragen. Was ist ähnlich? Was ist unterschiedlich? Welches Muster siehst du?",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.3.desc-2026-07-07T23:36:08.815260+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.3.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.4.desc-2026-07-07T23:36:08.815260+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T23:36:08.815260+00:00",
