    {
      "@id": "entity:source-privacy.auto_updates_desc",
      "@type": "prov:Entity",
      "prov:value": "Compliance rules are updated centrally as regulations change, so every classroom stays current without any manual work."
    },
    {
      "@id": "entity:target-privacy.auto_updates_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "\"Die Compliance-Regeln werden zentral aktualisiert, wenn sich die Vorschriften ändern, damit jeder Klassenraum auf dem neuesten Stand bleibt, ohne dass manuelle Arbeit erforderlich ist.\"\n\n(Translation notes: \"Compliance rules\" translates to \"Compliance-Regeln\", \"centrally updated\" translates to \"zentral aktualisiert\", \"every classroom stays current\" translates to \"jeder Klassenraum auf dem neuesten Stand bleibt\", and \"without any manual work\" translates to \"ohne dass manuelle Arbeit erforderlich ist\".)",
      "generated_by": {
        "@id": "activity:translation-privacy.auto_updates_desc-2026-07-08T00:19:34.421662+00:00"
      },
      "used_source": {
        "@id": "entity:source-privacy.auto_updates_desc"
      }
    },
