    {
      "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-08T00:22:56.963797+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T00:22:56.963797+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr",
      "@type": "prov:Entity",
      "prov:value": "When you upload a PDF or CSV, Ollama extracts the criteria once and caches them. Re-uploading the same file skips Ollama entirely (checksum match). A different file triggers re-extraction. Pre-seeded state sets were hand-authored and are always instant. Sets expire annually — you'll see a warning near the expiry date."
    },
    {
      "@id": "entity:target-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-v1",
      "@type": "prov:Entity",
      "prov:value": "Wenn Sie eine PDF- oder CSV-Datei hochladen, extrahiert Ollama die Kriterien einmal und speichert sie im Cache. Das erneute Hochladen der gleichen Datei überspringt Ollama vollständig (Übereinstimmung der Prüfsumme). Eine andere Datei löst die erneute Extraktion aus. Vorab gesetzte Zustandsmengen wurden von Hand erstellt und sind immer sofort verfügbar. Mengen verlieren jährlich ihre Gültigkeit – Sie werden eine Warnung kurz vor dem Ablaufdatum sehen.",
      "generated_by": {
        "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-08T00:22:56.963797+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr"
      }
    },
