    {
      "@id": "activity:translation-team_1_bio-2026-07-08T00:31:15.250526+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T00:31:15.250526+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-team_1_bio",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam."
    },
    {
      "@id": "entity:target-team_1_bio-v1",
      "@type": "prov:Entity",
      "prov:value": "Paul war zehn Jahre als Lehrer tätig, vier Jahre in der Edtech-Branche und experimentiert seit zwei Jahrzehnten damit, das Lernen aus Büchern und Klassenzimmern herauszulösen. Peripateticware nutzt die Fortschritte bei LLMs und nutzt mobile Technologien, um Schülern zu ermöglichen, von der Welt aus zu lernen, unter der Führung ihrer Lehrer, wohin sie auch immer gehen.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-07-08T00:31:15.250526+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      }
    },
