      "@id": "activity:translation-curriculumImportPage.description-2026-07-08T00:31:37.317602+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T00:31:37.317602+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-curriculumImportPage.description",
      "@type": "prov:Entity",
      "prov:value": "Upload a PDF or CSV of official state academic standards (TEKS, NGSS, Common Core, etc.). Ollama extracts each standard for review. Once saved as a global set, all teachers and homeschool parents can map their activities against these standards. Re-uploading the same file skips processing (checksum cache)."
    },
    {
      "@id": "entity:target-curriculumImportPage.description-v1",
      "@type": "prov:Entity",
      "prov:value": "Laden Sie eine PDF- oder CSV-Datei mit offiziellen landeseigenen akademischen Standards (TEKS, NGSS, Common Core usw.) hoch. Ollama extrahiert jeden Standard zur Überprüfung. Sobald sie als globale Menge gespeichert sind, können alle Lehrer und Homeschool-Eltern ihre Aktivitäten darauf abbilden. Das Hochladen der gleichen Datei überspringt die Verarbeitung (Checksumme-Cache).",
      "generated_by": {
        "@id": "activity:translation-curriculumImportPage.description-2026-07-08T00:31:37.317602+00:00"
      },
      "used_source": {
        "@id": "entity:source-curriculumImportPage.description"
      }
    },
    {
      "@id": "activity:translation-pages_admin_platformadminpage.reason_required_for_audit_log-2026-07-08T00:31:37.317602+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T00:31:37.317602+00:00",
      "actor": {
